import { finding } from '../../engine/checks/helpers/findings.mjs';

// Only the latest owner comment is judged: earlier turns were judged at their
// own Stops, and a transcript is append-only, so an old omission never converges.
//
// The class is stated at the moment of replying, prompted beside the owner's
// comment (prompt-submit.md) rather than discovered here — this rule is the
// backstop for a reply that skipped it, and every firing costs a whole turn.
// So it asks only where an answer carries information: a comment that requests
// nothing routes nowhere, and its class would be `other` by construction.
const BARE_PHRASE = new RegExp(
  '^(?:'
  + 'lgtm|looks good(?: to me)?|ship it|merge(?: it)?|approved?|'
  + 'bump version|'
  + 'y(?:es|ep)?|no(?:pe)?|ok(?:ay)?|sure|right|correct|'
  + 'thanks?(?: you)?|ta|'
  + 'go ahead|carry on|continue|proceed|do it|please do|keep going'
  + ')(?:[\\s,.!—-]+(?:please|now|then|continue|go ahead))*[\\s.!?]*$',
  'i',
);

// A comment that asks for nothing: the WHOLE of it is an approval or a command
// phrase the project already routes by other means ("LGTM" merges, "bump version"
// runs the version workflow). Anchored at both ends — "yes — and rename the
// button" opens with one and is a request.
export const isBarePhrase = (text) => BARE_PHRASE.test((text || '').trim());

const rule = {
  id: 'comment-classification',
  severity: 'blocking',
  description: 'The reply to the owner\'s latest substantive comment must declare an explicit `Comment class:` line',
  doc: 'packs/basics/RULES.md',
  scope: 'work',
  why: 'the class decides the flow (correction / feature / process-change); an unclassified comment tends to become an unrouted one-off patch',

  run(work) {
    const lastOwnerTurn = work.conversation().ownerTurns().last();
    if (!lastOwnerTurn.exists || lastOwnerTurn.classified()) return [];
    if (isBarePhrase(lastOwnerTurn.text)) return [];

    const menu = lastOwnerTurn.classLine() !== null;
    return [finding(rule, {
      file: '(conversation)',
      what: menu
        ? `the reply to the owner's latest comment ("${lastOwnerTurn.excerpt(70)}…") names the whole menu on its \`Comment class:\` line, which classifies nothing`
        : `the reply to the owner's latest comment ("${lastOwnerTurn.excerpt(70)}…") declares no \`Comment class:\` line`,
      fix: 'state the classification explicitly — a line `Comment class: <the class(es) that apply>`, drawn from correction / feature / '
        + 'process-change / other, anywhere in your reply text',
    })];
  },
};

export default rule;
EOF
