cd /home/user/Claudinite; cat > engine-tests/pack_loader/pack-prompt-notes.test.mjs <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, writeFileSync, cpSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

// The per-turn note channel: the text an active pack puts BESIDE the owner's
// comment, every turn. Generic like the session-start runner beside it — core
// discovers the file structurally and never learns what a pack says in it — and
// bounded, because this one is paid on every prompt of every session.
function makeCorpus(packs) {
  const root = mkdtempSync(join(tmpdir(), 'claudinite-corpus-'));
  mkdirSync(join(root, 'packs'), { recursive: true });
  mkdirSync(join(root, 'engine', 'pack_loader'), { recursive: true });
  cpSync(join(REPO_ROOT, 'engine', 'pack_loader'), join(root, 'engine', 'pack_loader'), { recursive: true });
  cpSync(join(REPO_ROOT, 'engine', 'hooks'), join(root, 'engine', 'hooks'), { recursive: true });
  cpSync(join(REPO_ROOT, 'engine', 'checks'), join(root, 'engine', 'checks'), { recursive: true });
  cpSync(join(REPO_ROOT, 'engine', 'version.mjs'), join(root, 'engine', 'version.mjs'));
  for (const [id, { note, ...manifest }] of Object.entries(packs)) {
    mkdirSync(join(root, 'packs', id), { recursive: true });
    writeFileSync(
      join(root, 'packs', id, 'pack.mjs'),
      `export default ${JSON.stringify({ id, detect: null, worldRules: [], ruleRoutingGuidance: { belongs: `whatever ${id} owns`, excludes: `whatever ${id} does not own` }, ...manifest })};\n`,
    );
    if (note !== undefined) writeFileSync(join(root, 'packs', id, 'prompt-submit.md'), note);
  }
  return root;
}

function makeProject(declaration) {
  const root = mkdtempSync(join(tmpdir(), 'claudinite-proj-'));
  writeFileSync(join(root, '.claudinite-checks.json'), `${JSON.stringify(declaration, null, 2)}\n`);
  return root;
}

function run(corpus, project, env = {}) {
  const r = spawnSync('node', [join(corpus, 'engine', 'hooks', 'userpromptsubmit-command.mjs')], {
    encoding: 'utf8',
    env: { ...process.env, CLAUDE_PROJECT_DIR: project, ...env },
  });
  // Exit 2 on this event REJECTS the owner's prompt, and any non-zero exit costs
  // the note. A note channel may never be able to do either.
  assert.equal(r.status, 0, r.stderr);
  return r.stdout;
}

test('an active pack\'s note is emitted; an undeclared pack\'s is not', () => {
  const corpus = makeCorpus({
    alpha: { version: 1, note: 'ALPHA NOTE\n' },
    beta: { version: 1, note: 'BETA NOTE\n' },
  });
  const out = run(corpus, makeProject({ packs: [{ id: 'alpha' }] }));
  assert.match(out, /ALPHA NOTE/);
  assert.doesNotMatch(out, /BETA NOTE/);
});

test('a pack shipping no note says nothing, and a repo declaring nothing stays silent', () => {
  const corpus = makeCorpus({ alpha: { version: 1 } });
  assert.equal(run(corpus, makeProject({ packs: [{ id: 'alpha' }] })).trim(), '');
  assert.equal(run(corpus, makeProject({ packs: [] })).trim(), '');
});

test('an over-long note is truncated rather than paid in full on every turn', () => {
