// The per-turn note channel: the short text each ACTIVE pack contributes beside
// every owner comment, read from `<pack>/prompt-submit.md`.
//
// WHY A SECOND PROSE CHANNEL, given a pack's RULES.md already loads every session.
// Position. A rule read once at session start competes with every other rule for
// attention across a long session, and the ones it loses are the ones that apply
// at the moment a comment arrives: `comment-classification` fired 204 times in 31
// days, each firing a blocked Stop and a whole turn spent emitting one line the
// session had already been told to emit. This channel puts that kind of rule
// where the decision is made — alongside the prompt — so the Stop-hook rule is
// the backstop it was meant to be rather than the delivery mechanism.
//
// WHICH MAKES ITS COST THE POINT: paid on every prompt of every session, in a
// finite context window. So a note is a STATIC file (no subprocess, nothing to
// compute — what a pack can only know at session time belongs in its
// session-start.mjs), it is capped, and the cap is the engine's, not a knob a
// pack can raise. A pack with nothing that must be re-read every turn ships none.
//
// Structural discovery and activation-gating, exactly as the session-start runner
// states them: core never names the pack whose note it forwards.
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

export const NOTE_FILE = 'prompt-submit.md';

const MAX_BYTES = () => Number(process.env.CLAUDINITE_PROMPT_NOTE_MAX_BYTES) || 600;

// Every active pack's note, in discovery order, capped per pack. Async because
// pack discovery is; returns '' when this repo runs no Claudinite, declares
// nothing, or no declared pack ships a note.
export async function promptNotes({ root, loaderDir }) {
  let config = { packs: [] };
  const configPath = join(root, '.claudinite-checks.json');
  if (!existsSync(configPath)) return '';
  try { config = JSON.parse(readFileSync(configPath, 'utf8')); } catch { return ''; }

  const { loadPacks, isActive } = await import(join(loaderDir, 'pack-registry.mjs'));
  const packs = (await loadPacks({ localRoot: root })).filter((p) => isActive(p, config));

  const cap = MAX_BYTES();
  const parts = [];
  for (const pack of packs) {
    const file = join(pack.dir, NOTE_FILE);
    if (!existsSync(file)) continue;
    let text;
    try { text = readFileSync(file, 'utf8').trim(); } catch { continue; }
    if (!text) continue;
    if (Buffer.byteLength(text, 'utf8') > cap) {
      text = `${Buffer.from(text, 'utf8').subarray(0, cap).toString('utf8')} [truncated at ${cap} bytes — a per-turn note is paid on every prompt]`;
    }
    parts.push(text);
  }
  return parts.join('\n');
}
EOF
