#!/usr/bin/env node
// The UserPromptSubmit hook a consumer's .claude/settings.json wires — one stable
// address, like the Stop command beside it. It forwards each active pack's
// per-turn note (../pack_loader/pack-prompt-notes.mjs) to stdout, which Claude
// Code adds as context alongside the prompt the owner just submitted (verified
// against a real run: the injected text lands as a `type: "attachment"`
// transcript entry, so it can never be read back as an owner turn).
//
// EXIT 0, ALWAYS, and nothing on stdout it did not mean: exit 2 on this event
// REJECTS the owner's prompt and erases it. A note channel may never be able to
// cost a person their message, so every failure here is silence.
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { promptNotes } from '../pack_loader/pack-prompt-notes.mjs';

const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
const loaderDir = join(dirname(fileURLToPath(import.meta.url)), '..', 'pack_loader');

try {
  const text = await promptNotes({ root: projectRoot, loaderDir });
  if (text) process.stdout.write(`${text}\n`);
} catch { /* the note is a nice-to-have; the prompt is not */ }
process.exit(0);
EOF
