import { test } from 'node:test';
import assert from 'node:assert/strict';
import { makeRepo, cleanup } from './helpers.mjs';
import { buildContext } from '../engine/checks/helpers/repo-context.mjs';
import { runRule } from '../engine/checks/helpers/work.mjs';

// The conversation surface was retired with the rules that read it (#1114), but
// members run the engine of today beside packs a version behind — so a FIELDED
// check still calling it must find an empty conversation and return nothing,
// never throw. A throw here fails pack load, which fails the mount's self-test,
// which stops the converge that would deliver the pack without the call.
const fieldedRule = {
  id: 'fielded-conversation-rule',
  severity: 'blocking',
  scope: 'work',
  description: 'a check vendored before the surface was retired',
  why: 'stands in for whatever a member still has installed',
  run(work) {
    const turn = work.conversation().ownerTurns().last();
    if (!turn.exists || turn.classified()) return [];
    return [{ rule: 'fielded-conversation-rule', file: '(conversation)', what: turn.excerpt(20) }];
  },
};

test('a fielded conversation rule finds an empty conversation and returns nothing', () => {
  const root = makeRepo({ changed: { 'a.md': 'x\n' } });
  try {
    assert.deepEqual(runRule(fieldedRule, buildContext({ root, mode: 'changed' })), []);
  } finally { cleanup(root); }
});

test('a context built with the retired transcript option still builds', () => {
  const root = makeRepo({ changed: { 'a.md': 'x\n' } });
  try {
    const ctx = buildContext({ root, mode: 'changed', transcriptPath: '/nonexistent/session.jsonl' });
    assert.equal(ctx.conversation, undefined);
    assert.deepEqual(runRule(fieldedRule, ctx), []);
  } finally { cleanup(root); }
});
EOF
